description[0] = "<tbody><tr><td><p>Concepto DIAN <A href='oficio_dian_2766_2026.htm#0' >2766</A> de 2026</p><p>Concepto DIAN <A href='oficio_dian_6043_2025.htm#0' >6043</A> de 2025</p><p>Concepto DIAN <A href='oficio_dian_7364_2024.htm#0' >7364</A> de 2024</p><p>Oficio DIAN <A href='oficio_dian_904121_2022.htm#INICIO' >904121</A> de 2022</p><p>Oficio DIAN <A href='oficio_dian_915608_2021.htm#INICIO' >915608</A> de 2021</p><p>Oficio DIAN <A href='oficio_dian_910043_2021.htm#INICIO' >910043</A> de 2021</p><p>Oficio DIAN <A href='oficio_dian_908376_2021.htm#INICIO' >908376</A> de 2021</p><p>Oficio DIAN <A href='oficio_dian_906829_2021.htm#INICIO' >906829</A> de 2021</p><p>Oficio DIAN <A href='oficio_dian_900635_2021.htm#INICIO' >900635</A> de 2021</p><p>Oficio DIAN <A href='oficio_dian_26710_2019.htm#INICIO' >26710</A> de 2019</p> </td></tr></tbody>";
