description[0] = "<tbody><tr><td><p>Concepto DIAN <A href='oficio_dian_15200_2025.htm#0' >15200</A> de 2025</p><p>Oficio DIAN <A href='oficio_dian_904292_2022.htm#INICIO' >904292</A> de 2022</p><p>Oficio DIAN <A href='oficio_dian_902595_2022.htm#INICIO' >902595</A> de 2022</p><p>Oficio DIAN <A href='oficio_dian_22588_2019.htm#INICIO' >22588</A> de 2019</p><p>Oficio DIAN <A href='oficio_dian_20462_2019.htm#INICIO' >20462</A> de 2019</p><p>Oficio DIAN <A href='oficio_dian_2400_2018.htm#INICIO' >2400</A> de 2018 </p><p>Oficio DIAN <A href='oficio_dian_0145_2018.htm#INICIO' >145</A> de 2018 </p><p>Oficio DIAN <A href='oficio_dian_2059_2017.htm#INICIO' >2059</A> de 2017 </p> </td></tr></tbody>";
