function insRow4165()
{
var description = new Array();
description[0] = "<tbody><tr><td><p><span class='b_aj'>Texto sustituido por el Decreto 2125 de 2018:</span></p><p>ART&Iacute;CULO 1.8.3.1. &lt;Art&iacute;culo sustituido por el art&iacute;culo <A href='decreto_2125_2018.htm#1' >1</A> del Decreto 2125 de 2018. El nuevo texto es el siguiente:&gt; La Comisi&oacute;n Nacional Mixta de Gesti&oacute;n Tributaria y Aduanera estar&aacute; integrada, para el periodo presidencial 2018-2022, por los representantes de los siguientes gremios: </p><p>- ASOBANCARIA. Gremio representativo del sector financiero colombiano. </p><p>- ANDI. Asociaci&oacute;n Nacional de Empresarios de Colombia. </p><p>- SAC. Sociedad de Agricultores de Colombia. </p><p>- ANALDEX. Asociaci&oacute;n Nacional de Comercio Exterior. </p><p>- FITAC. Federaci&oacute;n Colombiana de Agentes Log&iacute;sticos en Comercio Internacional. </p><p>- FENALCO. Federaci&oacute;n Nacional de Comerciantes. </p><p>PAR&Aacute;GRAFO. Los gremios asistir&aacute;n a trav&eacute;s de sus representantes legales o apoderados debidamente acreditados.</p><p><span class='b_aj'>Texto original del Decreto 1625 de 2016:</span></p><p>ART&Iacute;CULO 1.8.3.1. La Comisi&oacute;n Nacional Mixta de Gesti&oacute;n Tributaria y Aduanera estar&aacute; integrada para lo que resta del actual periodo presidencial, por los representantes de los siguientes gremios:</p><p>-- Asobancaria. Gremio representativo del sector financiero colombiano.</p><p>-- ANDI Asociaci&oacute;n Nacional de Empresarios de Colombia.</p><p>-- Camacol. C&aacute;mara Colombiana de la Construcci&oacute;n.</p><p>-- SAC. Sociedad de Agricultores de Colombia.</p><p>-- Analdex. Asociaci&oacute;n Nacional de Comercio Exterior.</p><p>-- Fitac. Federaci&oacute;n Colombiana de Agentes Log&iacute;sticos en Comercio Internacional.</p><p>PAR&Aacute;GRAFO. Los gremios asistir&aacute;n a trav&eacute;s de sus representantes legales o apoderados debidamente acreditados.</p><p><span class='i_aj'>(Art&iacute;culo <A href='decreto_2310_2014.htm#1' >1</A>o, Decreto <A href='decreto_2310_2014.htm#Inicio' >2310</A> de 2014) (Vigencia del Decreto <A href='decreto_2310_2014.htm#Inicio' >2310</A> de 2014. El Decreto <A href='decreto_2310_2014.htm#Inicio' >2310</A> de 2014 rige a partir de la fecha de su expedici&oacute;n y hasta el seis (6) de agosto de 2018. (Art&iacute;culo <A href='decreto_2310_2014.htm#2' >2</A>o, Decreto <A href='decreto_2310_2014.htm#Inicio' >2310</A> de 2014))</span>.</p> </td></tr></tbody>";
var z=document.getElementById('Table4165').rows[0];
if (z==null) {
	var x=document.getElementById('Table4165').insertRow(0);
	var y=x.insertCell(0);
	y.innerHTML=description;
	document.getElementById('Table4165').style.display = "block";
	}
else {
	document.getElementById('Table4165').deleteRow(0);
	document.getElementById('Table4165').style.display = "none";
	}
}
