description[0] = "<tbody><tr><td><p>Ley 1955 de 2019; Art. <A href='ley_1955_2019.htm#97' >97</A>; Art. <A href='ley_1955_2019.htm#304' >304</A> </p> </td></tr></tbody>";
var z=document.getElementById('Table4271').rows[0];
